CREATE TABLE `con_article` (
  `id` bigint(200) NOT NULL AUTO_INCREMENT,
  `title` varchar(256) DEFAULT NULL COMMENT '标题',
  `url_id` bigint(20) DEFAULT NULL COMMENT '对外URL数字ID(发布时随机生成15位,不可枚举)',
  `content` longtext COMMENT '文章内容',
  `description` varchar(1024) DEFAULT NULL COMMENT '文章摘要',
  `is_auto_description` char(1) DEFAULT NULL COMMENT '0：为自动生成，1：为空',
  `cover` varchar(256) DEFAULT NULL COMMENT '缩略图',
  `is_top` char(1) DEFAULT '0' COMMENT '是否置顶（0否，1是）',
  `status` char(1) DEFAULT '1' COMMENT '状态（0已发布，1草稿）',
  `category_id` bigint(20) DEFAULT NULL COMMENT '所属分类id',
  `view_count` bigint(200) DEFAULT '0' COMMENT '访问量',
  `favorite_count` bigint(200) DEFAULT '0' COMMENT '收藏量',
  `comment_count` bigint(200) DEFAULT '0' COMMENT '评论总数(已通过+已驳回)',
  `is_comment` char(1) DEFAULT '1' COMMENT '是否允许评论 1是，0否',
  `create_by` bigint(20) DEFAULT NULL,
  `create_time` datetime DEFAULT NULL,
  `update_by` bigint(20) DEFAULT NULL,
  `update_time` datetime DEFAULT NULL,
  `is_deleted` tinyint(3) DEFAULT '0' COMMENT '删除标志（0代表未删除，1代表已删除）',
  PRIMARY KEY (`id`) USING BTREE,
  UNIQUE KEY `uk_con_article_url_id` (`url_id`) USING BTREE,
  KEY `idx_deleted_status` (`is_deleted`,`status`) USING BTREE,
  KEY `idx_deleted_create_time` (`is_deleted`,`create_time`) USING BTREE,
  KEY `idx_category_id` (`category_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=19 DEFAULT CHARSET=utf8mb4 ROW_FORMAT=COMPACT COMMENT='文章表';
