  KEY `idx_role_id` (`role_id`) USING BTREE,
  KEY `idx_admin_id` (`user_id`) USING BTREE
) ENGINE=InnoDB AUTO_INCREMENT=339 DEFAULT CHARSET=utf8 ROW_FORMAT=COMPACT COMMENT='用户角色';
